#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCore: FfiConverter {

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = Core

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> Core {
        return Core(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: Core) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Core {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if (ptr == nil) {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: Core, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCore_lift(_ pointer: UnsafeMutableRawPointer) throws -> Core {
    return try FfiConverterTypeCore.lift(pointer)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCore_lower(_ value: Core) -> UnsafeMutableRawPointer {
    return FfiConverterTypeCore.lower(value)
}




public struct AccountState {
    public var accountUrl: String
    public var contactUrl: String?
    public var rootFolderUrl: String?
    public var moduleSettingsUrl: String?
    public var configUrl: String?
    public var folders: [String]
    public var inbox: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(accountUrl: String, contactUrl: String?, rootFolderUrl: String?, moduleSettingsUrl: String?, configUrl: String?, folders: [String], inbox: String?) {
        self.accountUrl = accountUrl
        self.contactUrl = contactUrl
        self.rootFolderUrl = rootFolderUrl
        self.moduleSettingsUrl = moduleSettingsUrl
        self.configUrl = configUrl
        self.folders = folders
        self.inbox = inbox
    }
}

#if compiler(>=6)
extension AccountState: Sendable {}
#endif


extension AccountState: Equatable, Hashable {
    public static func ==(lhs: AccountState, rhs: AccountState) -> Bool {
        if lhs.accountUrl != rhs.accountUrl {
            return false
        }
        if lhs.contactUrl != rhs.contactUrl {
            return false
        }
        if lhs.rootFolderUrl != rhs.rootFolderUrl {
            return false
        }
        if lhs.moduleSettingsUrl != rhs.moduleSettingsUrl {
            return false
        }
        if lhs.configUrl != rhs.configUrl {
            return false
        }
        if lhs.folders != rhs.folders {
            return false
        }
        if lhs.inbox != rhs.inbox {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(accountUrl)
        hasher.combine(contactUrl)
        hasher.combine(rootFolderUrl)
        hasher.combine(moduleSettingsUrl)
        hasher.combine(configUrl)
        hasher.combine(folders)
        hasher.combine(inbox)
    }
}



